<?php require_once __DIR__.'/../bootstrap.php';require_admin();$page=valid_page();$per=25;$anime=(int)($_GET['anime_id']??0);$lang=trim($_GET['language']??'');$active=$_GET['active']??'';$where=[];$p=[];if($anime){$where[]='v.anime_id=?';$p[]=$anime;}if($lang!==''){$where[]='v.language=?';$p[]=$lang;}if($active!==''){$where[]='v.active=?';$p[]=(int)$active;}$w=$where?' WHERE '.implode(' AND ',$where):'';$c=$pdo->prepare("SELECT COUNT(*) FROM video_sources v$w");$c->execute($p);$pages=max(1,ceil($c->fetchColumn()/$per));$s=$pdo->prepare("SELECT v.*,a.title,e.number FROM video_sources v JOIN anime a ON a.id=v.anime_id JOIN episodes e ON e.id=v.episode_id$w ORDER BY v.id DESC LIMIT ? OFFSET ?");foreach($p as $i=>$v)$s->bindValue($i+1,$v);$s->bindValue(count($p)+1,$per,PDO::PARAM_INT);$s->bindValue(count($p)+2,($page-1)*$per,PDO::PARAM_INT);$s->execute();$title='Sources — AniRead';include __DIR__.'/../includes/header.php';?><h1>Authorized video sources</h1><form class="filters"><input class="input" name="language" value="<?=e($lang)?>" placeholder="Language"><select name="active"><option value="">All statuses</option><option value="1" <?=selected($active,'1')?>>Active</option><option value="0" <?=selected($active,'0')?>>Inactive</option></select><button class="btn">Filter</button></form><p><a class="btn" href="source-edit.php">Add source</a></p><table class="table"><tr><th>Anime</th><th>Ep</th><th>Language</th><th>Server</th><th>Active</th><th></th></tr><?php foreach($s as $v):?><tr><td><?=e($v['title'])?></td><td><?=e($v['number'])?></td><td><?=e($v['language'])?></td><td><?=e($v['server_name'])?></td><td><?=$v['active']?'Yes':'No'?></td><td><a class="btn alt" href="source-edit.php?id=<?=$v['id']?>">Edit</a></td></tr><?php endforeach;?></table><?php page_links($page,$pages,'sources.php?language='.rawurlencode($lang).'&active='.rawurlencode($active));include __DIR__.'/../includes/footer.php';
